// One-off: puts each weapon perk of Skills.json into a gun branch (Pistol, Rifle, Shotgun), with its place
// inside the branch and the two requirement changes that keep every branch self-contained.
const fs = require('fs');
const file = process.argv[2];
let text = fs.readFileSync(file, 'utf8');
const plan = {
	Weapon_PistolHeadshot: { branch: 'Pistol', col: 0, row: 0 },
	Weapon_Headshot: { branch: 'Pistol', col: 1, row: 0 },
	Weapon_PrecisionRecovery: { branch: 'Pistol', col: 1, row: 1 },
	Weapon_RifleFar: { branch: 'Rifle', col: 0, row: 0 },
	Weapon_FireRate: { branch: 'Rifle', col: 1, row: 0 },
	Weapon_Recoil: { branch: 'Rifle', col: 1, row: 1 },
	Weapon_ShotgunClose: { branch: 'Shotgun', col: 0, row: 0 },
	Weapon_ReloadSpeed: { branch: 'Shotgun', col: 1, row: 0, requires: 'Weapon_Damage' },
	Weapon_EnchantBuildUp: { branch: 'Shotgun', col: 0, row: 1, requires: 'Weapon_ShotgunClose' },
};
const nl = text.includes('\r\n') ? '\r\n' : '\n';
for (const [id, p] of Object.entries(plan)) {
	const start = text.indexOf('"Id": "' + id + '"');
	if (start < 0) throw new Error('missing ' + id);
	const end = text.indexOf('}' + nl + '\t\t}', start) >= 0 && false ? 0 : text.indexOf(nl + '\t\t}', start);
	let block = text.slice(start, end);
	const before = block;
	block = block.split('"Tree": "Weapon",').join('"Tree": "Weapon",' + nl + '\t\t\t"Branch": "' + p.branch + '",');
	block = block.replace(/"Column": \d+,/, '"Column": ' + p.col + ',');
	block = block.replace(/"Row": \d+/, '"Row": ' + p.row);
	if (p.requires) block = block.replace(/"Requires": \[ "[A-Za-z_]+" \]/, '"Requires": [ "' + p.requires + '" ]');
	if (block === before) throw new Error('no change for ' + id);
	text = text.slice(0, start) + block + text.slice(end);
}
fs.writeFileSync(file, text);
console.log('ok');

